namespace ghidra.app.plugin.core.compositeeditor;





using docking;
using generic.theme;
using ghidra.util;
using ghidra.util.exception;

/**
 * Action for use in the structure data type editor.
 * This action has help associated with it.
 */
public class CreateInternalStructureAction : CompositeEditorTableAction {

	private static Icon ICON = new GIcon("icon.plugin.composite.editor.create");
	public static string ACTION_NAME = "Create Structure From Selection";
	private static string GROUP_NAME = COMPONENT_ACTION_GROUP;
	private static string DESCRIPTION =
		"Create a new structure from the selected components and replace them with it.";
	private static string[] POPUP_PATH = new string[] { ACTION_NAME };

	public CreateInternalStructureAction(StructureEditorProvider provider) : base(provider, ACTION_NAME, GROUP_NAME, POPUP_PATH, null, ICON)
    {
		setDescription(DESCRIPTION);
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (!isEnabledForContext(context)) {
			return;
		}
		int[] selectedComponentRows = model.getSelectedComponentRows();
		bool hasComponentSelection = model.hasComponentSelection();
		bool hasContiguousSelection = model.isContiguousComponentSelection();
		if (selectedComponentRows.length == 0) {
			return;
		}

		if (!hasComponentSelection || !hasContiguousSelection) {
			return;
		}

		Arrays.sort(selectedComponentRows);
		int numComponents = model.getNumComponents();
		int maxRow = selectedComponentRows[selectedComponentRows.length - 1];
		if (maxRow < numComponents) {
			createStructure();
		}

		Swing.runLater(() => {
			provider.toFront();
			provider.requestFocus();
			provider.editorPanel.requestFocus();
			provider.editorPanel.table.requestFocus();
		});
	}

	private void createStructure() {
		try {
			((StructureEditorModel) model).createInternalStructure();
		}
		catch (UsrException e) {
			model.setStatus(e.getMessage(), true);
		}
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return !hasIncompleteFieldEntry() && isCreateInternalStructureAllowed();
	}

	private bool isCreateInternalStructureAllowed() {
		return model.hasComponentSelection() && model.isContiguousComponentSelection();
	}
}
